use n_core::{fetch::kline::Kline,v3::ablation::c_structure::{Structure,clear_trace,take_trace}};
fn bar(min:usize,h:f64,l:f64,c:f64,short:bool)->Kline{let f=|v|if short{240.-v}else{v};Kline{datetime:format!("2026-01-05 09:{min:02}:00"),open:f(c),high:f(if short{l}else{h}),low:f(if short{h}else{l}),close:f(c),volume:1.,hold:1.}}
fn history(short:bool)->Vec<Kline>{let spec=[(110.,100.),(109.,96.),(116.,102.),(114.,104.),(113.,101.),(115.,105.)];(1..=30).map(|i|{let(h,l)=spec[(i-1)/5];bar(i,h,l,(h+l)/2.,short)}).collect()}
fn setup(short:bool,push:bool,wick:bool)->Structure{clear_trace();let mut s=Structure::default();for b in history(short){assert!(!s.observe(&b,"2026-01-05 09:00:00",if short{-1.}else{1.},1.,push,wick));}s}
#[test]
fn higher_low_is_known_only_after_full_right5m_and_is_price_mirrored(){for short in [false,true]{let mut s=setup(short,false,false);let traces=take_trace();let a=traces.iter().find(|t|t.kind=="activated").unwrap();assert_eq!(a.pivot_ts.as_deref(),Some("2026-01-05 09:25:00"));assert_eq!(a.ts,"2026-01-05 09:30:00");assert_eq!(a.price,Some(if short{139.}else{101.}));assert!(s.observe(&bar(31,102.,99.,99.,short),"2026-01-05 09:00:00",if short{-1.}else{1.},1.,false,false));}}
#[test]
fn wick_and_close_failures_differ_without_retroactive_confirmation_bar(){for short in [false,true]{let mut a=setup(short,false,false);let mut b=setup(short,false,true);let k=bar(31,110.,99.,108.,short);assert!(!a.observe(&k,"2026-01-05 09:00:00",if short{-1.}else{1.},1.,false,false));assert!(b.observe(&k,"2026-01-05 09:00:00",if short{-1.}else{1.},1.,false,true));}}
#[test]
fn push_mode_waits_for_later_intervening_peak_clear_and_does_not_reuse_B_level(){for short in [false,true]{let mut s=setup(short,true,false);assert!(!take_trace().iter().any(|t|t.kind=="activated"));let sign=if short{-1.}else{1.};assert!(!s.observe(&bar(31,118.,116.,117.,short),"2026-01-05 09:00:00",sign,1.,true,false));assert!(take_trace().iter().any(|t|t.kind=="activated"&&t.ts=="2026-01-05 09:31:00"));assert!(s.observe(&bar(32,102.,99.,99.,short),"2026-01-05 09:00:00",sign,1.,true,false));}}
#[test]
fn unbroken_candidate_cannot_be_reactivated_after_it_failed_while_waiting(){let mut s=setup(false,true,false);assert!(!s.observe(&bar(31,102.,99.,99.,false),"2026-01-05 09:00:00",1.,1.,true,false));assert!(take_trace().iter().any(|t|t.kind=="candidate_invalidated"));assert!(!s.observe(&bar(32,118.,116.,117.,false),"2026-01-05 09:00:00",1.,1.,true,false));assert!(!take_trace().iter().any(|t|t.kind=="activated"));}
#[test]
fn no_post_entry_full_candles_means_no_structure_and_missing_minutes_do_not_join(){clear_trace();let mut s=Structure::default();for b in history(false){s.observe(&b,"2026-01-05 09:30:00",1.,1.,false,false);}assert!(take_trace().is_empty());let mut s=Structure::default();for b in history(false).into_iter().filter(|b|!b.datetime.contains(":12:")){s.observe(&b,"2026-01-05 09:00:00",1.,1.,false,false);}assert!(!take_trace().iter().any(|t|t.kind=="candidate"));}
#[test]
fn prefix_structure_trace_cannot_change_when_future_minutes_are_appended(){clear_trace();let mut s=Structure::default();let h=history(false);for b in &h[..25]{s.observe(b,"2026-01-05 09:00:00",1.,1.,false,false);}let before=take_trace();for b in &h[25..]{s.observe(b,"2026-01-05 09:00:00",1.,1.,false,false);}let after=take_trace();clear_trace();let mut full=Structure::default();for b in h{full.observe(&b,"2026-01-05 09:00:00",1.,1.,false,false);}let all=take_trace();assert_eq!(serde_json::to_value(before.into_iter().chain(after).collect::<Vec<_>>()).unwrap(),serde_json::to_value(all).unwrap());}
#[test]
fn actual_exit_waits_until_next_open_and_original_fill_risk_is_preserved(){use n_core::{v2::replay::ReplayEvent,v3::ablation::{evaluate_research,Experiment,Policy,ResearchRules}};let mut bars=vec![bar(0,101.,100.,100.,false)];bars.extend(history(false));bars.push(bar(31,102.,99.,99.,false));bars.push(bar(32,101.,99.,99.,false));let mut e=ReplayEvent{symbol:"RB0".into(),direction:"up".into(),warning_ts:"2026-01-05 08:59:00".into(),entry:100.,stop:74.,target:150.,risk:26.,tick_size:1.,..Default::default()};e.setup_features.setup_quality=4.;let ex=Experiment{policy:Policy::OriginalS1,no_follow_bar:None,slip_ticks:1.,fee_ticks:0.};let rules=ResearchRules{c_structure:true,..Default::default()};let r=evaluate_research(&e,&bars,&[],&Default::default(),ex,10.,None,rules);assert_eq!(r.evaluation.entry_ts.as_deref(),Some("2026-01-05 09:00:00"));assert_eq!(r.evaluation.exit_ts.as_deref(),Some("2026-01-05 09:32:00"));assert_eq!(r.evaluation.exit_reason.as_deref(),Some("c_structure_failed"));assert_eq!(r.evaluation.risk,27.);let prefix=evaluate_research(&e,&bars[..32],&[],&Default::default(),ex,10.,None,rules);assert_ne!(prefix.evaluation.status,"closed");}
